function buildProjectTypeGuidance(workspaceRoot: string): string {
    // Use cached result from detectPythonEnvironment (populated during workspace_summary)
    // This is a sync wrapper that returns empty string if no cached result yet
    return _cachedProjectGuidance ?? '';
}

/** Cached project type guidance string, populated by async buildProjectTypeGuidanceAsync */
let _cachedProjectGuidance: string | null = null;

async function buildProjectTypeGuidanceAsync(workspaceRoot: string): Promise<string> {
    const pyEnv = await detectPythonEnvironment(workspaceRoot);
    if (!pyEnv) {
        _cachedProjectGuidance = '';
        return '';
    }

    const lines: string[] = ['\n## Python Project Environment', 'This is a Python project. Use run_command for these tasks:'];

    // Test command
    if (pyEnv.testFramework === 'pytest') {
        lines.push('- Run tests: `python -m pytest -v` (or `pytest -v`)');
    } else {
        lines.push('- Run tests: `python -m unittest discover`');
    }

    // Lint command
    if (pyEnv.linter) {
        const cmd = pyEnv.linter === 'ruff' ? 'ruff check .' : pyEnv.linter === 'flake8' ? 'flake8 .' : 'pylint .';
        lines.push(`- Lint code: \`${cmd}\``);
    }

    // Type checker
    if (pyEnv.typeChecker) {
        lines.push(`- Type check: \`${pyEnv.typeChecker} .\``);
    }

    // Formatter
    if (pyEnv.formatter) {
        lines.push(`- Format code: \`${pyEnv.formatter} .\``);
    }

    // Install deps
    const installCmd = {
        pip: 'pip install -r requirements.txt',
        poetry: 'poetry install',
        pipenv: 'pipenv install',
        uv: 'uv sync',
    }[pyEnv.packageManager] ?? 'pip install -r requirements.txt';
    lines.push(`- Install deps: \`${installCmd}\``);
    lines.push('- Run scripts: `python <script.py>`');
    lines.push('- Check syntax: `python -m py_compile <file.py>`');

    // Detected tools summary
    const tools: string[] = [pyEnv.packageManager];
    if (pyEnv.linter) { tools.push(pyEnv.linter); }
    if (pyEnv.typeChecker) { tools.push(pyEnv.typeChecker); }
    if (pyEnv.testFramework) { tools.push(pyEnv.testFramework); }
    if (pyEnv.formatter && pyEnv.formatter !== pyEnv.linter) { tools.push(pyEnv.formatter); }
    lines.push(`\nDetected tools: ${tools.join(', ')}`);
    if (pyEnv.venvPath) { lines.push(`Virtual env: ${pyEnv.venvPath}`); }

    _cachedProjectGuidance = lines.join('\n');
    return _cachedProjectGuidance;
}

// â"€â"€ Hierarchical context file scanning â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€
// Scans the workspace for AGENTS.md, CLAUDE.md, or .ollamaforge.md files at
// the root and up to 2 directory levels deep. Content is injected into the
// system prompt so the model has per-directory conventions without manual ingestion.
//
// File priority (highest wins on conflict): .ollamaforge.md > AGENTS.md > CLAUDE.md
// Only files â‰¤ 8000 chars are included to prevent context bloat.
//
// ARCHITECTURE.md is also loaded from the workspace root (root only, not subdirs)
// as a separate always-present section -- it's auto-generated by the code indexer.
const CONTEXT_FILE_NAMES = ['.ollamaforge.md', 'AGENTS.md', 'CLAUDE.md'];
const MAX_CONTEXT_FILE_BYTES = 8000;

async function loadHierarchicalContext(workspaceRoot: string): Promise<string> {
    const sections: string[] = [];
    try {
        // â"€â"€ .ollamaforge/context.md (highest priority -- strategic project/engagement context) â"€â"€
        // This is the intentional home for persistent, session-spanning agent context:
        // project goals, constraints, rules of engagement, team conventions, environment facts.
        // Loaded before everything else so it frames all subsequent context.
        const agentContextPath = path.join(workspaceRoot, '.ollamaforge', 'context.md');
        try {
            const stat = fs.statSync(agentContextPath);
            if (stat.isFile()) {
                const content = fs.readFileSync(agentContextPath, 'utf8').slice(0, 32_000);
                sections.push(`### .ollamaforge/context.md (project context -- always apply)\n${content.trim()}`);
                logInfo(`[context-files] Loaded .ollamaforge/context.md (${content.length} chars)`);
            }
        } catch { /* file doesn't exist yet -- skip */ }

        // â"€â"€ .ollamaforge/feedback.md (self-improvement: past response issues flagged by user) â"€â"€
        // Loaded early so the agent sees its own failure patterns before generating responses.
        // Each entry is a labeled example of what went wrong -- agent should avoid repeating them.
        const feedbackPath = path.join(workspaceRoot, '.ollamaforge', 'feedback.md');
        try {
            const stat = fs.statSync(feedbackPath);
            if (stat.isFile()) {
                const content = fs.readFileSync(feedbackPath, 'utf8').slice(0, 8_000);
                sections.push(`### .ollamaforge/feedback.md (past response issues -- avoid repeating these)\nThe following are behaviors the user has flagged as problems in previous responses. Study them and do NOT repeat these patterns:\n${content.trim()}`);
                logInfo(`[context-files] Loaded feedback.md (${content.length} chars)`);
            }
        } catch { /* file doesn't exist yet -- skip */ }

        // â"€â"€ ARCHITECTURE.md (root only, loaded first as project structure reference) â"€â"€
        const archPath = path.join(workspaceRoot, 'ARCHITECTURE.md');
        try {
            const stat = fs.statSync(archPath);
            if (stat.isFile()) {
                const content = fs.readFileSync(archPath, 'utf8').slice(0, MAX_CONTEXT_FILE_BYTES);
                sections.push(`### ARCHITECTURE.md (auto-generated project structure)\n${content.trim()}`);
                logInfo(`[context-files] Loaded ARCHITECTURE.md (${content.length} chars)`);
            }
        } catch { /* file doesn't exist yet -- skip */ }

        // â"€â"€ DEPLOYMENT.md (root only -- SSH users, scp patterns, service names) â"€â"€
        const deployPath = path.join(workspaceRoot, 'DEPLOYMENT.md');
        try {
            const stat = fs.statSync(deployPath);
            if (stat.isFile()) {
                const content = fs.readFileSync(deployPath, 'utf8').slice(0, MAX_CONTEXT_FILE_BYTES);
                sections.push(`### DEPLOYMENT.md (SSH users, deploy commands, service names -- always check before forming ssh/scp commands)\n${content.trim()}`);
                logInfo(`[context-files] Loaded DEPLOYMENT.md (${content.length} chars)`);
            }
        } catch { /* file doesn't exist -- skip */ }

        // â"€â"€ PLAN.md (root only, loaded second -- development plan and backlog) â"€â"€
        const planPath = path.join(workspaceRoot, 'PLAN.md');
        try {
            const stat = fs.statSync(planPath);
            if (stat.isFile()) {
                const content = fs.readFileSync(planPath, 'utf8').slice(0, MAX_CONTEXT_FILE_BYTES);
                sections.push(`### PLAN.md (development plan and backlog)\n${content.trim()}`);
                logInfo(`[context-files] Loaded PLAN.md (${content.length} chars)`);
            }
        } catch { /* file doesn't exist -- skip */ }

        // â"€â"€ Convention/guide files: root + immediate subdirectories â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€
        const candidates: string[] = [workspaceRoot];
        try {
            const entries = fs.readdirSync(workspaceRoot, { withFileTypes: true });
            for (const e of entries) {
                if (!e.isDirectory()) { continue; }
                if (SKIP_DIRS.has(e.name) || e.name.startsWith('.')) { continue; }
                candidates.push(path.join(workspaceRoot, e.name));
            }
        } catch { /* can't list root -- just use root */ }

        const seen = new Set<string>(); // deduplicate by canonical path
        for (const dir of candidates) {
            for (const fname of CONTEXT_FILE_NAMES) {
                const fpath = path.join(dir, fname);
                if (seen.has(fpath)) { continue; }
                try {
                    const stat = fs.statSync(fpath);
                    if (!stat.isFile()) { continue; }
                    const content = fs.readFileSync(fpath, 'utf8').slice(0, MAX_CONTEXT_FILE_BYTES);
                    const rel = path.relative(workspaceRoot, fpath).replace(/\\/g, '/');
                    sections.push(`### ${rel}\n${content.trim()}`);
                    seen.add(fpath);
                    logInfo(`[context-files] Loaded ${rel} (${content.length} chars)`);
                    break; // highest-priority file wins for this directory
                } catch { /* file doesn't exist or can't be read -- skip */ }
            }
        }
    } catch { /* never let context scanning break agent startup */ }

    // â"€â"€ Pending proposed rules reminder â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€â"€
    // If the dream agent has written proposed_rules.md with unaccepted rules,
    // inject a one-line reminder so the agent mentions it to the user naturally.
    try {
        const proposedPath = path.join(workspaceRoot, '.ollamaforge', 'proposed_rules.md');
        const stat = fs.statSync(proposedPath);
        if (stat.isFile()) {
            const content = fs.readFileSync(proposedPath, 'utf8');
            const ruleCount = (content.match(/^## Rule:/gm) || []).length;
            if (ruleCount > 0) {
                sections.push(`### Pending: proposed behavioral rules\nThe dream agent has proposed ${ruleCount} new rule${ruleCount === 1 ? '' : 's'} based on past feedback. Remind the user once per session: "You have ${ruleCount} proposed rule${ruleCount === 1 ? '' : 's'} ready to review -- run \`Ollama Forge: Accept Proposed Rules\` from the command palette to apply them."`);
                logInfo(`[context-files] Found ${ruleCount} pending proposed rule(s)`);
            }
        }
    } catch { /* no proposed_rules.md -- skip */ }

    if (sections.length === 0) { return ''; }
    return `## Project Context Files\nThe following files define project conventions, architecture, and guidelines:\n\n${sections.join('\n\n')}`;
}

/** Snapshot the mtime (ms) of each context file currently on disk. */
function snapshotContextFileMtimes(workspaceRoot: string): Map<string, number> {
    const result = new Map<string, number>();
    const roots = [workspaceRoot];
    try {
        const entries = fs.readdirSync(workspaceRoot, { withFileTypes: true });
        for (const e of entries) {
            if (e.isDirectory() && !SKIP_DIRS.has(e.name) && !e.name.startsWith('.')) {
                roots.push(path.join(workspaceRoot, e.name));
            }
        }
    } catch { /* ignore */ }
    // Also check .ollamaforge/context.md
    const specialFiles = [
        path.join(workspaceRoot, '.ollamaforge', 'context.md'),
        path.join(workspaceRoot, 'ARCHITECTURE.md'),
        path.join(workspaceRoot, 'PLAN.md'),
    ];
    for (const fpath of specialFiles) {
        try { result.set(fpath, fs.statSync(fpath).mtimeMs); } catch { /* skip */ }
    }
    for (const dir of roots) {
        for (const fname of CONTEXT_FILE_NAMES) {
            const fpath = path.join(dir, fname);
            try { result.set(fpath, fs.statSync(fpath).mtimeMs); } catch { /* skip */ }
        }
    }
    return result;
}

async function buildSystemPromptAsync(autoSaveMemory: boolean, workspaceRoot?: string): Promise<string> {
    const [guidance, hierarchicalCtx] = await Promise.all([
        workspaceRoot ? buildProjectTypeGuidanceAsync(workspaceRoot) : Promise.resolve(''),
        workspaceRoot ? loadHierarchicalContext(workspaceRoot) : Promise.resolve(''),
    ]);
    return buildSystemPrompt(autoSaveMemory, workspaceRoot, guidance, hierarchicalCtx);
}

function buildSystemPrompt(autoSaveMemory: boolean, workspaceRoot?: string, projectGuidance?: string, hierarchicalCtx?: string): string {
    const now = new Date();
    const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    const timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    const activeEditor = vscode.window.activeTextEditor;
    const activeLanguage = activeEditor?.document.languageId ?? '';
    const activeFile = activeEditor ? vscode.workspace.asRelativePath(activeEditor.document.uri) : '';

    const autoSaveBlock = autoSaveMemory ? `
## Memory -- save facts silently as you learn them
When you discover an IP, hostname, path, URL, framework, tool, convention, or decision: call memory_tier_write immediately, without announcing it.
Tiers: 0=infrastructure (IPs/paths/ports), 1=tools/frameworks, 2=current work, 3=conventions, 4=solutions/workarounds.
One fact per entry, atomic. Never save passwords, tokens, or credentials.
Stale correction: if a tool result contradicts a loaded memory entry, delete the old entry and write the corrected fact before continuing.
Session end: write one Tier 2 summary -- what was done, what is open, any decisions made.
` : '';

    const workspaceInfo = workspaceRoot ? `Workspace: ${workspaceRoot}` : '';

    const isServerAdminWorkspace = workspaceRoot && (
        fs.existsSync(path.join(workspaceRoot, 'hosts_inventory.json')) ||
        fs.existsSync(path.join(workspaceRoot, 'ssh')) ||
        fs.existsSync(path.join(workspaceRoot, 'server_infrastructure'))
    );
    const serverAdminBlock = isServerAdminWorkspace ? `
## Infrastructure workspace
Check memory_search and hosts_inventory.json before SSHing anywhere. Save every discovered IP/path to Tier 0 immediately. Flag [warn] any service with install_method not in {binary, systemd, docker, apt, pip, npm}.
` : '';

    // Detect workspace characteristics for conditional prompt sections.
    // Avoids injecting SSH/BusyBox/data-pipeline guidance on local-only coding tasks.
    const hasSshFiles = workspaceRoot && (
        fs.existsSync(path.join(workspaceRoot, 'ssh')) ||
        fs.existsSync(path.join(workspaceRoot, '.ssh')) ||
        (() => { try { return fs.readdirSync(workspaceRoot).some(f => /\.(sh|bash)$/.test(f)); } catch { return false; } })()
    );
    const hasRemoteHints = isServerAdminWorkspace || hasSshFiles;
    const hasCsvOrLargeData = workspaceRoot && (() => {
        try { return fs.readdirSync(workspaceRoot).some(f => /\.(csv|log|parquet|jsonl)$/i.test(f)); } catch { return false; }
    })();

    const remoteExecBlock = hasRemoteHints ? `
## Remote execution (SSH / BusyBox targets)
For any logic that needs to run on a remote host, the sequence is always:
  1. write_file: scripts/myscript.py  -- write the complete script locally
  2. run_command: scp scripts/myscript.py HOST:/tmp/myscript.py  -- before forming this command, check DEPLOYMENT.md, context.md, or earlier ssh commands in this session for the correct username. If unsure, ask -- do NOT guess root@.
  3. run_command: ssh HOST test -f /tmp/myscript.py && echo EXISTS
  4. run_command: ssh HOST python3 /tmp/myscript.py

Never use ssh with inline Python (python3 -c) or heredocs (<< EOF). On Windows, Git Bash mangles quote nesting before ssh sees it -- even single-line python3 -c fails. On BusyBox/ash targets, neither form is supported. Simple commands over ssh are always fine: "ssh host ls /path", "ssh host systemctl restart svc", "ssh host 'cd /dir && ./run.sh'". Anything beyond a short one-liner must use the write_file + scp + ssh pattern -- do not attempt inline python first.
**NEVER use ssh ... sed -i to edit a remote file** -- the local shell mangles quotes and backslashes before ssh sees them, corrupting the file. To edit a remote file: edit the local copy with edit_file, then scp it up, then ssh to move it into place.
**Avoid long ssh && chains** -- when chaining "cmd1 && cmd2 && cmd3" over ssh, a silent failure in cmd1 can leave the system in a half-applied state. For multi-step remote operations, write a script locally and scp+run it instead.
After every scp, verify the file exists on the remote before running it -- once. If the file was confirmed present, proceed immediately without re-checking.
Copy remote paths verbatim from tool results -- never reconstruct from memory or local paths.
Destructive scripts (mv, rm, archive): add DRY_RUN=True mode, run dry-run first, show output, then re-run with DRY_RUN=False after the user sees the preview.
Every script must print a structured summary as its last line: {"processed": N, "changed": N, "errors": N, "sample": [...]}
` : '';

    const dataPipelineBlock = (hasRemoteHints || hasCsvOrLargeData) ? `
## Data pipeline tasks (large files, multi-stage, remote processing)
- Large files (>500 lines or any CSV/log): write a script to process and summarize -- never read raw into context.
- Multi-stage tasks: write named stage scripts (stage_1_extract.py, stage_2_transform.py). Each stage writes a summary JSON and prints its result. Call task_checkpoint between stages.
- Multi-file review: write one script that inspects all files and prints a summary. Never read files one at a time into context.
- After any data modification: run a verification script that confirms counts and samples before declaring done.
- Clean up /tmp scripts on remote hosts after the task is done.
` : '';

    const searchCfg = getSearchConfig();
    const comfyCfg = getComfyUIConfig();
    const webSearchLine = searchCfg.url
        ? `  web_search         -- search the web via SearXNG (${searchCfg.url}); use for examples, docs, libraries\n  web_fetch          -- fetch and read a web page by URL`
        : '';
    const generateImageLine = comfyCfg.url
        ? `  generate_image     -- generate an image via ComfyUI (${comfyCfg.url}); use for diagrams, mockups, report visuals`
        : '';

    return `You are an expert AI coding and systems assistant inside VS Code.
Current date: ${dateStr}, ${timeStr}.${activeLanguage ? ` Active file: ${activeFile} (${activeLanguage}).` : ''}${workspaceInfo ? `\nWorkspace: ${workspaceRoot}` : ''}
Always work from actual project files -- never answer from training data alone.

## Tools
  workspace_summary  -- project structure overview
  read_file          -- read a file (prefer over shell cat)
  search_files       -- regex search across files
  find_files         -- glob file search
  edit_file          -- replace old_string with new_string in a file
  shell_read         -- read-only shell (git, env queries)
  gather_context     -- read 2--8 files in parallel (read-only)
  run_command        -- state-changing shell commands (mv, cp, rm, scp, ssh, install)
  memory_search / memory_list / memory_write / memory_tier_write / memory_delete
  system_map_update / system_map_query / system_map_visualize
  get_diagnostics    -- VS Code errors/warnings for a file
  read_terminal      -- VS Code terminal output${webSearchLine ? `\n${webSearchLine}` : ''}${generateImageLine ? `\n${generateImageLine}` : ''}

## Shell environment
${buildShellExamples(detectShellEnvironment(), workspaceRoot)}

## Output format
Every response is one of:
  A) One line of visible text explaining what you are doing + one or more tool calls
  B) A final answer (no tool calls) -- only when fully done or genuinely blocked

Never: write text and stop without calling a tool. Never: announce an action without immediately doing it. Never: summarize a result and stop -- call the next tool or give the final answer.
BAD: "I will now read esphome/smart_bag.yaml to check progress." (announces intent, then stops -- no tool call)
GOOD: "Checking progress." + read_file({"path": "esphome/smart_bag.yaml"})  (brief text + immediate tool call in the same response)
After every 3 tool calls, write one visible sentence so the user knows what is happening.
**Answer once, then stop.** When the task is done, give the final answer exactly once. Do NOT re-summarize after cleanup steps, verification calls, or file-existence checks -- those are housekeeping, not a reason to repeat the conclusion. If you already gave the answer and the only remaining step is cleanup (rm, verify file gone, etc.), do the cleanup silently and stop. Never emit the same summary twice.
Questions to the user go at the very end of the response, on their own line, never buried mid-paragraph.
No decorative emoji, no "## Analysis" headers, no filler sign-offs. Lead with the answer.
Never pre-draft file content in your thinking -- decide what to write, then emit the tool call directly.

## Execution discipline
**Check before creating.** Before writing any new script or file, call find_files or shell_read with "ls scripts/" to see if one already exists that does the same job. Reuse and extend existing scripts rather than writing duplicates. Only create a new file when nothing in the workspace covers the task.
**Run, don't describe.** When the user asks to sync, copy, run, execute, or perform an operational task -- run the relevant script or command immediately. Do NOT describe what the script does or list its features. The user knows what it does; they want it done. If a relevant script exists, call run_command with it now.
**Observe before acting — once.** If you haven't read the file yet this session, read it first. If you already read it this turn or a recent turn, do NOT re-read it — use what you already have and act. Never re-read a file you read in the last 3 turns.
**Use exact values from tool results.** Copy paths, IDs, and string literals verbatim from tool output into subsequent calls. Never invent a placeholder or reconstruct from memory.
**Prefer current files over dated backups.** When you see both a plain config file (e.g. '.env', 'config.yaml') and dated backup variants (e.g. 'env_20240205', 'config.yaml.bak', 'settings_old'), always read the plain/undated file first -- it is the live config. Only read dated backups when explicitly asked or when the current file does not exist.
**Act on every tool result.** If a result contradicts your plan, update the plan. Ignoring a tool result is a failure.
**Exit 0 is not correctness.** After running a command, read its output once to confirm it worked. If you already confirmed it worked, move on — do NOT re-check the same output again.
**Done means verified — once.** Written → syntax-checked → executed → output confirmed. One verification pass is enough. Do not run the same verification check more than once.
**Before declaring done: check the tracking document.** If the user has a tracking document (any file ending in .md, .txt, or .todo that contains a checklist of tasks — e.g. "progress.md", "tasks.md", "TODO.md", "PLAN.md", or a file mentioned by name in the conversation), read it with read_file BEFORE saying the task is complete. Count unchecked items (lines starting with \`- [ ]\` or \`[ ]\` or numbered items without a ✓). If any items remain unchecked, continue working — do NOT declare done.

## Staying on track
**Confirmed plan = authorization for all steps.** When the user says yes/go ahead/proceed, execute the entire sequence without pausing to ask "want me to continue-- or "should I do X next-- at each step. Only pause for a genuine blocker: unexpected error, irreversible action not in the plan, or a value only the user can provide.
**"Move X from A to B" is ambiguous — always ask first.** When the user says "move scripts/code/logic from X to Y" where X and Y are platform/service names (discord, matrix, slack, telegram, database names, service names) rather than filesystem paths, do NOT assume they mean a filesystem \`mv\` or directory rename. They almost certainly mean: update the code so it targets platform B instead of platform A (change imports, API calls, config). Before doing anything, ask: "Do you want me to (1) update the code so these scripts send to [B] instead of [A], or (2) physically move the files to a different directory?" One sentence, one question.
**Batch, don't enumerate.** Never check items one at a time with repeated ls/find calls. Write one script that checks everything at once and prints a summary. If you are about to run the same command pattern a second time on a different item -- stop, write a loop, run it once.
**Never write a numbered plan or mid-task status list.** Do not write "1. Search for X, 2. Search for Y..." or "Current progress: [x] item A, [ ] item B" in your response. Writing the plan or status causes a spiral. Instead: act on the next item immediately. Each tool call IS the plan step. Only produce a summary when ALL items are complete.
**Never re-read a checklist to decide what to do next.** If you are working through a checklist, pick the next unchecked item and call a tool on it immediately. Do NOT re-enumerate remaining items, re-evaluate which are "actionable", or re-list what is done. Just act.
**No progress updates between items.** Do not write "I have completed X. Moving on to Y." between tool calls -- just make the next tool call silently. One visible sentence per 3 tool calls maximum.
**Use at least 3 sources when answering factual questions.** When the user asks how something works, which library/tool to use, or requests guidance they will act on — do not answer from a single search result. Run at least 3 web_search calls with different query angles (e.g. official docs, a tutorial, a community forum), then web_fetch the most authoritative result to verify the detail is current. Only form your answer after cross-referencing. State your sources.
**Two failures = skip and move on (research tasks).** If a web_search for a specific product returns no useful result twice, write "Not found on Amazon" for that item and immediately search for the next item. Do not spend more than 2 searches on any single item.
**Two failures = different approach (other tasks).** If the same non-search approach fails twice, stop and pick something fundamentally different. Do not retry with minor tweaks. After two different approaches both fail, explain the blocker and ask the user. **Never cycle through more than 4 total attempts at the same sub-problem** — if you haven't solved it in 4 attempts, tell the user what you've tried and what's blocking you.
**Dependency/install spirals: stop at 3.** If you are installing dependencies one at a time and each install either fails or reveals another missing dependency, STOP after 3 rounds. Do not keep chasing the chain. Instead: (1) collect the full list of what failed, (2) check if there is a bulk install script or requirements file you haven't tried, (3) search the web for the known incompatibility (e.g. "package X Python 3.13"), (4) tell the user exactly what is blocking and ask whether to continue or switch approach. Never install more than 3 packages in a row without re-validating that the root import now works.
**Configuration spirals: stop at 2.** If you write a config file and the service fails to start or rejects it twice, do NOT keep tweaking the config from memory or guesswork. Stop immediately, fetch the official documentation or a working example from the web (web_search or web_fetch the GitHub README/docs), and only rewrite the config once you have confirmed the correct format from a real source.
**One question at a time.** If you must ask the user something, ask the single most important question. Never ask for information you can discover yourself with a tool.
**Clean up temp scripts when done.** Any helper scripts you wrote to accomplish the task (files in scripts/, /tmp/, or named like stage_*.py, check_*.py, fix_*.py, validate_*.py, migrate_*.py, convert_*.py) are temporary. Delete them with run_command before declaring the task complete, unless the user explicitly asked you to keep the script.
**Local scratch work stays in the workspace.** Never use /tmp or the OS temp dir for local clones, scratch files, or intermediate data. Use .ollamaforge/tmp/ instead (it is gitignored and workspace-local). /tmp is only acceptable for scripts being scp'd to a remote host.
**Don't run long scripts — hand them to the user.** Before running a Python script with run_command, ask yourself: will this finish in under 60 seconds? If it crawls files (os.walk, glob **), reads large datasets (pd.read_csv, iterrows), makes network calls in a loop (requests, paramiko, scp), or touches a large database (cursor.execute over many rows), it will timeout. Instead: (1) tell the user the script is ready and give them the exact command to run themselves, OR (2) add a --limit N flag and run only a small sample to verify it works, then hand the full run to the user. Never silently let a long-running script time out and then retry it.

## File editing
- New file or full rewrite (<30 lines): write_file.
- Modify any existing file (any type -- .py, .ts, .scad, .yaml, .json, .html, .css, etc.): call read_file first. Use the exact content returned by read_file as the basis for old_string in edit_file, or as the basis for write_file content. Never write from memory -- not for any file type.
- edit_file fails: the tool result includes the relevant file section automatically. Use the line numbers shown and switch to edit_file_at_line. Do not retry edit_file with a different old_string guess. NEVER write a Python script to make file edits — use write_file with the full corrected content instead.
- After writing any source file: verify syntax once -- Python: "python3 -m py_compile <file>"; TypeScript/JS: "tsc --noEmit"; OpenSCAD: "openscad -o /tmp/check.stl <file>"; other types: use get_diagnostics. Fix any error before moving on. Do NOT re-verify the same file if you already verified it this session.
- OpenSCAD internal threads: bore at MAJOR_R using difference(), then OUTSIDE the difference block union annular ridge cylinders at MINOR_R. NEVER place thread rings inside difference() -- they will be subtracted (removed), not added. Pattern: \`difference() { cube([...]); translate([cx,cy,cz]) rotate([0,90,0]) cylinder(h=depth+1, r=MAJOR_R, center=true); }\` then separately \`for (i=[0:n-1]) { translate([cx, cy, cz_i]) rotate([0,90,0]) cylinder(h=pitch*0.55, r=MINOR_R, center=true); }\` where MINOR_R < MAJOR_R and the ridge cylinders sit inside the bore.
- Merging files: copy ACTUAL method bodies verbatim from the source file. Do NOT use placeholder comments like "# Implementation from X.py" or bare pass statements. Read the source first, copy real code.

${remoteExecBlock}${dataPipelineBlock}${autoSaveBlock}${serverAdminBlock}
## Cross-workspace system map
Call system_map_query only when the task explicitly involves SSH, a remote host, a shared service, or an inter-workspace dependency. Do NOT call it for local file edits, 3D printing, coding tasks, or anything that runs entirely on the local machine. Call system_map_update when you learn a new host, IP, port, or service relationship. Mirror critical facts (IPs, paths, URLs) to Tier 0 memory as well.

## Code graph tools
When asked to understand, navigate, or refactor a codebase, prefer graph tools over repeated read_file calls:
- \`graph_query\` — find functions/classes by name or keyword; returns callers, callees, and file locations. Use this BEFORE read_file when you need to locate where something lives.
- \`graph_status\` — shows indexing state, symbol count, and last index time. Call this if scope context seems missing or incomplete.
- \`graph_index\` — re-indexes the workspace after major refactors. Call when you rename files or move significant code.
The graph context (if shown above in "## Code Scope Context") is pre-loaded for the current query — use it before calling graph_query for the same symbols.

## Proposed rules
If context files include a "Pending: proposed behavioral rules" section, mention it once at the end of your first response this session. Do not repeat it.
${projectGuidance ?? (workspaceRoot ? buildProjectTypeGuidance(workspaceRoot) : '')}${hierarchicalCtx ? `\n\n${hierarchicalCtx}` : ''}`;
}

